body.script:

(function() {
  var iframe = document.getElementById('mainFrame');
  var loadingScreen = document.getElementById('loadingScreen');
  var loadStatus = document.getElementById('loadStatus');

  // URL met de Base64-gecodeerde inhoud
  var url = 'https://cdn.jsdelivr.net/gh/nxyder/schoolshi@b34987e19f10e4defea668965a4dd6c643fa933c/b64.txt';

  loadStatus.textContent = 'GameHub ophalen van ' + url + '...';

  // Haal de Base64 inhoud op
  fetch(url)
    .then(function(response) {
      if (!response.ok) {
        throw new Error('HTTP error! status: ' + response.status);
      }
      return response.text();
    })
    .then(function(base64Data) {
      loadStatus.textContent = 'Base64 geladen, aan het decoderen...';

      // Decodeer Base64 naar HTML
      var decodedHtml = atob(base64Data);

      loadStatus.textContent = 'GameHub laden in iframe...';

      // Schrijf naar iframe
      var doc = iframe.contentDocument || iframe.contentWindow.document;
      doc.open();
      doc.write(decodedHtml);
      doc.close();

      loadStatus.textContent = '✅ GameHub geladen!';

      // Verberg laadscherm na korte vertraging
      setTimeout(function() {
        loadingScreen.style.opacity = '0';
        setTimeout(function() {
          loadingScreen.style.display = 'none';
        }, 500);
      }, 600);
    })
    .catch(function(error) {
      loadStatus.textContent = '❌ Fout: ' + error.message;
      loadStatus.style.color = '#ef4444';
      console.error('Fout bij ophalen:', error);

      // Toon error in iframe
      var doc = iframe.contentDocument || iframe.contentWindow.document;
      doc.open();
      doc.write('<!DOCTYPE html><html><head><style>body{background:#0a0a0f;color:#fff;font-family:sans-serif;display:flex;align-items:center;justify-content:center;height:100vh;flex-direction:column;}</style></head><body>');
      doc.write('<h2 style="color:#ef4444;">⚠️ Kan GameHub niet laden</h2>');
      doc.write('<p style="color:#888;">Fout: ' + error.message + '</p>');
      doc.write('<p style="color:#555;font-size:0.8rem;margin-top:20px;">Controleer je internetverbinding en probeer opnieuw.</p>');
      doc.write('</body></html>');
      doc.close();
    });
})();
